<template><div class="page"><div class="section-title"><div><h2>后台任务</h2><span class="muted">告警自动分析、隔离建议与人工审批</span></div><n-button type="primary" @click="load">刷新</n-button></div><div class="panel"><n-data-table :columns="columns" :data="tasks" :loading="loading"/></div></div></template>
<script setup>import {h,ref,onMounted} from 'vue';import {backgroundApi} from '@/api';const tasks=ref([]),loading=ref(false);const columns=[{title:'告警',key:'alert_name'},{title:'Namespace',key:'namespace'},{title:'目标 Pod',key:'target_pod'},{title:'状态',key:'status'},{title:'创建时间',key:'created_at',render:r=>new Date(r.created_at).toLocaleString()},{title:'操作',key:'action',render:r=>r.status==='action_pending_approval'?h('span',{},[h('button',{class:'link-button',onClick:()=>decide(r.id,true)},'批准'),h('button',{class:'link-button',style:'margin-left:10px',onClick:()=>decide(r.id,false)},'拒绝')]):''}];async function load(){loading.value=true;try{tasks.value=(await backgroundApi.list()).tasks||[]}finally{loading.value=false}}async function decide(id,yes){await (yes?backgroundApi.approve(id):backgroundApi.reject(id));await load()}onMounted(load)</script>
